import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        System.out.println(result);
    }
}

public class Solution {
    public static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }
}

public class Snail {
    private String name;
    private int speed;
    public Snail(String name, int speed) {
        this.name = name;
        this.speed = speed;
    }
    public int move() {
        return speed;
    }
}

public class Solution {
    public static int simulateRace(int distance) {
        Snail fastSnail = new Snail("Turbo", 5);
        Snail slowSnail = new Snail("Gary", 2);
        int totalDistance = fastSnail.move() + slowSnail.move();
        return distance - totalDistance;
    }
}
